import Vue from 'vue'
import VueRouter from 'vue-router'
import RecruitmentPage from '../views/RecruitmentPage.vue'
import RecruitmentInfoPage from '../views/RecruitmentInfoPage.vue'
// 导入校园文化相关组件
import HomeView from '../lsh/HomeView.vue'
import CampusActivities from '../lsh/CampusActivities.vue'
import SchoolHistory from '../lsh/SchoolHistory.vue'
import StudentClubs from '../lsh/StudentClubs.vue'
import MoralEducation from '../lsh/MoralEducation.vue'
import MoralEducationPage from '../lsh/MoralEducationPage.vue'

Vue.use(VueRouter)

const routes = [
  {
    path: '/',
    redirect: '/home'  // 将根路径重定向到/home
  },
  {
    path: '/home',
    name: 'Home',
    component: () => import('../views/HomePage.vue')
  },
  {
    path: '/about',
    name: 'About',
    component: SchoolOverview
  },
  // 添加教学教研页面路由
  {
    path: '/teaching',
    name: 'Teaching',
    component: TeachingPage
  },
  {
    path: '/admission',
    name: 'Admission',
    component: RecruitmentPage,
    props: { activeTab: 'admission' }
  },
  {
    path: '/recruitment',
    name: 'Recruitment',
    component: RecruitmentPage,
    props: { activeTab: 'recruitment' }
  },
  {
    path: '/recruitment-info',
    name: 'RecruitmentInfo',
    component: RecruitmentInfoPage
  },
  {
    path: '/registration',
    name: 'Registration',
    component: RecruitmentPage,
    props: { activeTab: 'registration' }
  },
  {
    path: '/contact',
    name: 'Contact',
    component: RecruitmentPage,
    props: { activeTab: 'contact' }
  },
  
  // 校园文化路由
  {
    path: '/culture',
    name: 'Culture',
    component: () => import('../lsh/CampusCulture.vue')
  },
  {
    path: '/campus-activities',
    name: 'CampusActivities',
    component: () => import('../lsh/CampusCulture.vue'),
    props: { currentView: 'campus-activities' }
  },
  {
    path: '/student-clubs',
    name: 'StudentClubs',
    component: () => import('../lsh/CampusCulture.vue'),
    props: { currentView: 'student-clubs' }
  },
  {
    path: '/school-history',
    name: 'SchoolHistory',
    component: () => import('../lsh/CampusCulture.vue'),
    props: { currentView: 'school-history' }
  },
  {
    path: '/moral-education',
    name: 'MoralEducation',
    component: () => import('../lsh/CampusCulture.vue'),
    props: { currentView: 'moral-education' }
  }
]

const router = new VueRouter({
  mode: 'history',
  base: process.env.BASE_URL,
  routes
})

export default router
